<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue';import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';import {get,write,request} from '../../../../packages/shared/src/client';import {useOperations} from '../../../../packages/shared/src/operations';import {useTask,money,type Row} from '../../../../packages/shared/src/ui';import Status from '../../../../packages/shared/src/Status.vue';
import {learningProgress} from '../../../../packages/shared/src/learningProgress';
import {playbackTiming,type PlaybackState} from '../../../../packages/shared/src/playbackTiming';
import {useSession} from '../../../../packages/shared/src/session';
const session=useSession(),router=useRouter();
const localPlayback=ref(false),cloudPlayback=ref(false),capabilitiesFailed=ref(false);
const playbackUnavailable=computed(()=>capabilitiesFailed.value?'无法确认视频播放能力，请稍后刷新。':cloudPlayback.value?'当前页面尚未提供云视频播放器，请联系管理员。':'当前环境不支持云视频播放，本地播放也未启用。');
async function loadCapabilities(){try{const environment=await get<Row>('/environment');localPlayback.value=environment.capabilities?.localPlayback===true;cloudPlayback.value=environment.capabilities?.cloudPlayback===true;}catch{capabilitiesFailed.value=true;}}
const route=useRoute(),task=useTask(),ops=useOperations(),course=ref<Row>(),lesson=ref<Row>(),section=ref<Row>(),play=ref<Row>(),favorite=ref(false),added=ref(false),coverFailed=ref(false),note=ref(''),questions=ref<Row[]>([]),replies=ref<Row[]>([]),question=ref<Row>(),title=ref(''),description=ref(''),reply=ref(''),video=ref<HTMLVideoElement>(),moment=ref(0),tab=ref('catalogue'),discussionLoaded=ref(false),questionPage=ref(1),questionTotal=ref(0),onlyMine=ref(false),replyPage=ref(1),replyTotal=ref(0);
const loading=ref(false),readError=ref(''),playbackError=ref(''),busy=computed(()=>task.busy.value||loading.value);let loadRevision=0,playRevision=0,questionsRevision=0,repliesRevision=0;
const questionsLoading=ref(false),repliesLoading=ref(false),discussionError=ref(''),repliesReady=ref(false);
const owner=computed(()=>{try{const raw=atob(session.token.split('.')[1]!.replace(/-/g,'+').replace(/_/g,'/'));return raw.match(/"userId"\s*:\s*(?:"([0-9]+)"|([0-9]+))/)?.slice(1).find(Boolean)||session.token;}catch{return session.token;}});
const progressWriter=learningProgress(()=>owner.value,async(value,signal)=>{
 await request('/services/learning/learning-records',{method:'POST',signal,body:JSON.stringify({lessonId:value.lessonId,sectionId:value.sectionId,sectionType:1,moment:value.moment})});

});
const id=()=>String(route.params.id),sections=computed<Row[]>(()=>course.value?.chapters?.flatMap((c:Row)=>c.sections||[])||[]);
const owned=computed(()=>!!lesson.value?.id && Number(lesson.value.status)!==3 && (!lesson.value.expireTime || new Date(lesson.value.expireTime).getTime()>Date.now()));
const enrollmentEnded=computed(()=>Number(course.value?.status)===4||!!course.value?.purchaseEndTime && new Date(course.value.purchaseEndTime).getTime()<Date.now());
const timing=playbackTiming(()=>owner.value,
 (context,signal)=>request('/services/learning/learning-records/playback-sessions',{method:'POST',body:JSON.stringify({lessonId:context.lessonId,sectionId:context.sectionId}),signal}),
 (body,end,signal)=>request('/services/learning/learning-records/playback-sessions/'+(end?'end':'heartbeat'),{method:'POST',body:JSON.stringify(body),signal}));
const timeLabel=(milliseconds:unknown)=>{const seconds=Math.floor(Number(milliseconds||0)/1000);return Math.floor(seconds/60)+'分'+seconds%60+'秒';};
const timedRecord=computed(()=>timing.current.value||lesson.value?.records?.find((r:Row)=>String(r.sectionId)===String(section.value?.id)));
let timingTimer:ReturnType<typeof setInterval>|undefined;
function sample(state:PlaybackState){return {state,positionMillis:Math.max(0,Math.round((video.value?.currentTime||0)*1000)),rate:Math.max(.5,Math.min(2,video.value?.playbackRate||1))};}
function applyTiming(){const result=timing.current.value;if(!result||!section.value||!lesson.value)return;const rows:Row[]=lesson.value.records||(lesson.value.records=[]);let row=rows.find((r:Row)=>String(r.sectionId)===String(section.value!.id));if(!row){row={sectionId:section.value.id};rows.push(row);}const before=!!row.finished;Object.assign(row,result);if(!before&&result.finished)lesson.value.learnedSections=Number(lesson.value.learnedSections||0)+1;}
async function playback(state:PlaybackState){
 if(!owned.value||!section.value||Number(section.value.type)!==2||!play.value?.playUrl)return;
 const own=owner.value,selected=String(section.value.id),scope=playRevision;
 if(document.hidden)state='HIDDEN';
 if(!timing.current.value?.active){if(state!=='PLAYING')return;const started=await timing.start({owner:own,lessonId:String(lesson.value!.id),sectionId:selected});if(!started)return;}
 if(scope!==playRevision||own!==owner.value||selected!==String(section.value?.id))return;
 if(video.value&&(video.value.playbackRate<.5||video.value.playbackRate>2)){video.value.pause();timing.error.value='学习计时支持 0.5 至 2 倍速，请调整播放速度';return;}
 await timing.heartbeat(sample(state),state==='ENDED');applyTiming();
 if(timing.replaced.value)video.value?.pause();
}
async function finishPlayback(){if(timing.current.value?.active){const saved=await timing.heartbeat(sample(document.hidden?'HIDDEN':'PAUSED'),true);applyTiming();if(!saved&&![401,403,409].includes(timing.errorStatus.value))return false;}timing.reset();return true;}
async function retryTiming(){await timing.retry();applyTiming();}
async function restartTiming(){video.value?.pause();timing.reset();if(owned.value&&section.value&&await timing.start({owner:owner.value,lessonId:String(lesson.value!.id),sectionId:String(section.value.id)}))await video.value?.play();}
function visibilityChanged(){if(document.hidden){void playback('HIDDEN');video.value?.pause();}}
const completed=(item:Row)=>lesson.value?.records?.some((r:Row)=>String(r.sectionId)===String(item.id)&&r.finished);
const totalSections=computed(()=>Number(course.value?.sectionNum)||sections.value.length);
const progress=computed(()=>totalSections.value?Math.min(100,Math.round(Number(lesson.value?.learnedSections??sections.value.filter(completed).length)/totalSections.value*100)):0);
const plain=(value:unknown)=>String(value||'').replace(/<[^>]*>/g,'').replace(/&nbsp;/g,' ');
async function load(){
 const revision=++loadRevision,courseId=id(),token=session.token;loading.value=true;readError.value='';
 const current=()=>revision===loadRevision&&courseId===id()&&token===session.token;
 try{const detail=await get<Row>(token?'/services/course/course/'+courseId+'?withCatalogue=true&withTeachers=true':'/public/courses/'+courseId);if(!current())return;course.value=detail;
  if(token){const [saved,rights]=await Promise.all([get<{favorited:boolean}>('/favorites/'+courseId),get<Row>('/services/learning/learning-records/course/'+courseId)]);if(current()){favorite.value=saved.favorited;lesson.value=rights;}}
 }catch(error){if(current())readError.value=error instanceof Error?error.message:'课程加载失败';}finally{if(current())loading.value=false;}
}
function requireLogin(){if(session.token)return false;void router.push({path:'/login',query:{redirect:route.fullPath}});return true;}
async function enroll(){if(requireLogin())return;const result=await task.run(()=>ops.begin('trade','免费课报名','/orders/free-courses/'+id(),{}));if(result?.status==='SUCCEEDED'){await load();task.message.value=owned.value?'报名成功，选择小节开始学习吧':'报名成功，学习权限准备中，请稍后刷新页面';}else if(result)task.message.value='报名处理中，可在操作记录中继续查询';}
async function addCart(){if(requireLogin())return;await task.run(async()=>{await write('/services/trade/carts','POST',{courseId:id()});added.value=true;task.message.value='已加入购物车';});}
async function toggleFavorite(){if(requireLogin())return;await task.run(async()=>{await write('/favorites/'+id(),favorite.value?'DELETE':'PUT');favorite.value=!favorite.value;task.message.value=favorite.value?'已收藏，可在我的收藏中查看':'已取消收藏';});}
async function select(item:Row){
 if(!session.token&&Number(item.type)===2){requireLogin();return;}
 if(!owned.value&&Number(item.type)===2&&!item.trailer){task.message.value=lesson.value?.id?'学习权益已失效，请重新报名后学习':'报名后可学习当前小节';return;}
 if(!await record(true))return;
 if(!await finishPlayback())return;
 const revision=++playRevision,courseId=id(),token=session.token;section.value=item;play.value=undefined;playbackError.value='';
 const previous=lesson.value?.records?.find((r:Row)=>String(r.sectionId)===String(item.id));moment.value=Number(previous?.moment||0);
 if(Number(item.type)!==2)return;if(!localPlayback.value){task.message.value=playbackUnavailable.value;return;}
 try{const result=await get<Row>('/services/media/medias/signature/play?sectionId='+item.id);if(revision!==playRevision||id()!==courseId||token!==session.token)return;if(owned.value)await timing.start({owner:owner.value,lessonId:String(lesson.value!.id),sectionId:String(item.id)});if(revision===playRevision&&id()===courseId&&token===session.token)play.value=result;}
 catch(error){if(revision===playRevision&&id()===courseId&&token===session.token)playbackError.value=error instanceof Error?error.message:'视频加载失败';}
}
function resumeVideo(){if(video.value && Number.isFinite(video.value.duration))video.value.currentTime=Math.min(moment.value,Math.max(0,video.value.duration-0.2));}
async function continueLearning(){tab.value='catalogue';const next=sections.value.find(x=>!completed(x))||sections.value[0];if(next)await select(next);}
async function record(force=false){
 if(!owned.value||!section.value||Number(section.value.type)!==2||!play.value?.playUrl)return !progressWriter.error.value;
 const now=Math.floor(video.value?.currentTime??moment.value),ended=video.value?.ended===true;
 return progressWriter.record({owner:owner.value,courseId:id(),lessonId:String(lesson.value!.id),sectionId:String(section.value.id),moment:now,ended},force);
}
function resetCourse(){timing.reset();video.value?.pause();loadRevision++;playRevision++;questionsRevision++;repliesRevision++;questionsLoading.value=false;repliesLoading.value=false;repliesReady.value=false;discussionError.value='';course.value=undefined;lesson.value=undefined;section.value=undefined;play.value=undefined;favorite.value=false;coverFailed.value=false;questions.value=[];replies.value=[];question.value=undefined;added.value=false;tab.value='catalogue';discussionLoaded.value=false;questionPage.value=1;replyPage.value=1;note.value='';title.value='';description.value='';reply.value='';playbackError.value='';}
watch(owner,()=>{progressWriter.reset();timing.reset();},{flush:'sync'});
watch(tab,value=>{if(value!=='catalogue')video.value?.pause();});
async function leavePlayback(){if(!session.token)return true;if(!await record(true))return false;return finishPlayback();}
onBeforeRouteUpdate(leavePlayback);onBeforeRouteLeave(leavePlayback);

async function saveNote(){await task.run(async()=>{const op=await ops.begin('learning','保存私人笔记','/notes',{courseId:id(),sectionId:section.value?.id,moment:section.value?moment.value:undefined,content:note.value});if(op.status==='SUCCEEDED'){note.value='';task.message.value='笔记已保存';}else task.message.value='笔记保存中，可在操作记录中查询';});}
async function loadQuestions(){
 if(requireLogin())return;const revision=++questionsRevision,scope=loadRevision,courseId=id(),token=session.token;questionsLoading.value=true;discussionError.value='';
 const current=()=>revision===questionsRevision&&scope===loadRevision&&courseId===id()&&token===session.token;
 try{const result=await get<Row>('/services/learning/questions/page?courseId='+courseId+'&pageNo='+questionPage.value+'&pageSize=20&onlyMine='+onlyMine.value);if(current()){questions.value=result.list||[];questionTotal.value=Number(result.total||0);discussionLoaded.value=true;}}
 catch(error){if(current())discussionError.value=error instanceof Error?error.message:'课程互动加载失败';}finally{if(current())questionsLoading.value=false;}
}
async function ask(){const saved=await task.run(async()=>{if(!section.value)throw new Error('请先选择小节');const chapter=course.value?.chapters?.find((c:Row)=>c.sections?.some((s:Row)=>s.id===section.value!.id));const result=await ops.begin('learning','课程提问','/services/learning/questions',{courseId:id(),chapterId:chapter?.id,sectionId:section.value.id,title:title.value,description:description.value,anonymity:false});if(result.status!=='SUCCEEDED'){task.message.value='提问处理中，可在操作记录中继续查询';return false;}title.value='';description.value='';return true;});if(saved)await loadQuestions();}
async function answers(item:Row){
 if(question.value?.id!==item.id){replyPage.value=1;reply.value='';}question.value=item;replies.value=[];replyTotal.value=0;repliesReady.value=false;
 const revision=++repliesRevision,scope=loadRevision,token=session.token;repliesLoading.value=true;discussionError.value='';
 const current=()=>revision===repliesRevision&&scope===loadRevision&&token===session.token&&question.value?.id===item.id;
 try{const result=await get<Row>('/services/learning/replies/page?questionId='+item.id+'&pageNo='+replyPage.value+'&pageSize=20');if(current()){replies.value=result.list||[];replyTotal.value=Number(result.total||0);repliesReady.value=true;}}
 catch(error){if(current())discussionError.value=error instanceof Error?error.message:'回答加载失败';}finally{if(current())repliesLoading.value=false;}
}
async function respond(){if(!repliesReady.value||!question.value)return;const selected=question.value,scope=loadRevision;const saved=await task.run(async()=>{const result=await ops.begin('learning','回答课程问题','/services/learning/replies',{questionId:selected.id,content:reply.value,anonymity:false});if(scope!==loadRevision||question.value?.id!==selected.id)return false;if(result.status!=='SUCCEEDED'){task.message.value='回答处理中，可在操作记录中继续查询';return false;}reply.value='';return true;});if(saved && question.value)await answers(question.value);}
async function like(item:Row){await task.run(async()=>{const liked=!item.liked;await write('/services/remark/likes','POST',{bizId:item.id,bizType:'QA',liked});item.liked=liked;item.likedTimes=Math.max(0,Number(item.likedTimes||0)+(liked?1:-1));task.message.value=liked?'已点赞':'已取消点赞';});}
watch(()=>session.token,()=>{resetCourse();void load();});
watch(()=>route.params.id,()=>{resetCourse();void load();});
onMounted(async()=>{document.addEventListener('visibilitychange',visibilityChanged);timingTimer=setInterval(()=>{if(video.value&&!video.value.paused&&!video.value.ended&&!video.value.seeking)void playback(document.hidden?'HIDDEN':'PLAYING');},10000);await loadCapabilities();await load();if(route.query.sectionId){const target=sections.value.find(x=>String(x.id)===String(route.query.sectionId));if(target){await select(target);moment.value=Number(route.query.moment||moment.value);}}});
onBeforeUnmount(()=>{document.removeEventListener('visibilitychange',visibilityChanged);if(timingTimer)clearInterval(timingTimer);void record(true);void finishPlayback();loadRevision++;playRevision++;questionsRevision++;repliesRevision++;});
</script>
<template><div class="course-page"><RouterLink to="/" class="breadcrumb">课程中心 / 课程详情</RouterLink><Status :busy="busy||questionsLoading||repliesLoading" :error="task.error.value||readError||playbackError||discussionError" :message="task.message.value"/><div v-if="progressWriter.error.value" role="alert"><p>{{progressWriter.error.value}}</p><el-button @click="progressWriter.retry" :disabled="progressWriter.busy.value">重试保存学习进度</el-button></div><el-button v-if="readError" @click="load" :disabled="loading">重新加载课程</el-button>
<template v-if="course"><section class="course-intro card"><img v-if="course.coverUrl && !coverFailed" :src="course.coverUrl" :alt="course.name" class="course-intro-art actual-course-cover" @error="coverFailed=true"/><div v-else class="course-intro-art designed-cover"><small>天机学堂 · 在线课程</small><strong>{{course.name}}</strong><span>LEARN AT YOUR OWN PACE</span></div><div class="course-intro-copy"><h1>{{course.name}}</h1><p class="muted">{{totalSections}} 小节 · {{(course.teachers||[]).map((t:Row)=>t.name).filter(Boolean).join('、')||'天机学堂课程团队'}}</p><p v-if="course.introduce" class="content">{{plain(course.introduce)}}</p><p class="price">{{Number(course.price)===0?'免费课程':money(course.price)}}</p><div class="toolbar"><template v-if="!owned && enrollmentEnded"><el-button size="large" disabled>报名已结束</el-button><span class="muted">{{Number(course.status)===4?'课程已完结，不再接受新报名':'已超过报名截止时间'}}</span></template><template v-else-if="!owned"><el-button v-if="Number(course.price)!==0" type="primary" size="large" :disabled="busy" @click="addCart">加入购物车</el-button><el-button v-else type="primary" size="large" :disabled="busy" @click="enroll">免费报名</el-button><RouterLink v-if="added" to="/cart" class="text-action">去购物车结算 →</RouterLink></template><el-button v-else type="primary" size="large" @click="continueLearning" :disabled="busy">继续学习</el-button><el-button :disabled="busy" @click="toggleFavorite">{{favorite?'取消收藏':'收藏课程'}}</el-button><RouterLink v-if="owned" :to="'/exams?courseId='+id()">参加考试 →</RouterLink><RouterLink v-else-if="lesson?.id" :to="'/exams?courseId='+id()">查看考试记录 →</RouterLink><span v-else class="muted">报名后可参加考试</span></div><div v-if="owned" class="learning-progress"><span>课程学习进度</span><el-progress :percentage="progress"/></div></div></section>
<el-alert v-if="!busy && lesson?.id && !owned" class="enrollment-hint" title="学习权益已失效" description="学习进度、私人笔记和已有答卷仍保留。重新报名后可继续学习。" type="warning" :closable="false" show-icon/>
<el-tabs v-model="tab" class="course-tabs"><el-tab-pane label="课程目录" name="catalogue"/><el-tab-pane label="课程介绍" name="intro"/><el-tab-pane label="课程互动" name="discussion"/></el-tabs>
<section v-if="tab==='intro'" class="card"><h2>关于这门课程</h2><p class="content">{{plain(course.detail||course.introduce)||'课程介绍暂未完善，可以先查看课程目录了解学习内容。'}}</p><h3 v-if="course.usePeople">适用人群</h3><p>{{course.usePeople}}</p></section>
<div v-show="tab==='catalogue'" class="course-study-layout"><aside class="card syllabus"><h2>课程目录</h2><div v-for="chapter in course.chapters" :key="chapter.id"><h3>{{chapter.name}}</h3><button v-for="item in chapter.sections" :key="item.id" class="lesson-item" :class="{current:section?.id===item.id}" :disabled="busy || (!owned && Number(item.type)===2 && !item.trailer)" @click="select(item)"><span class="lesson-type">{{Number(item.type)===3?'测':'▶'}}</span><span>{{item.index}}. {{item.name}}<small>{{Number(item.type)===3?'考试':Math.ceil(Number(item.mediaDuration||0)/60)+' 分钟'}}<template v-if="!owned && Number(item.type)===2"> · {{item.trailer?'可试看':'报名后学习'}}</template></small></span><span v-if="completed(item)" class="lesson-done">已完成</span></button></div><el-empty v-if="!sections.length" description="课程目录正在完善"/></aside>
<article class="card lesson-workspace"><template v-if="section"><h2>{{section.name}}</h2><RouterLink v-if="Number(section.type)===3 && owned" class="text-action" :to="'/exams?courseId='+id()">前往考试 →</RouterLink><RouterLink v-else-if="Number(section.type)===3 && lesson?.id" class="text-action" :to="'/exams?courseId='+id()">查看考试记录 →</RouterLink><p v-else-if="Number(section.type)===3" class="muted">报名后可参加考试</p><template v-else><video v-if="localPlayback && play?.playUrl" ref="video" :src="play.playUrl" controls class="course-player" @loadedmetadata="resumeVideo" @timeupdate="moment=Math.floor(video!.currentTime);record()" @playing="playback('PLAYING')" @waiting="playback('BUFFERING')" @seeking="playback('SEEKING')" @seeked="playback(video?.paused?'PAUSED':'PLAYING')" @ratechange="playback(video?.paused?'PAUSED':'PLAYING')" @ended="record(true);playback('ENDED')" @pause="record(true);playback('PAUSED')"/><el-alert v-else-if="!localPlayback" :title="playbackUnavailable" type="warning" :closable="false"/><el-alert v-else-if="play" title="当前视频播放渠道暂不可用，请联系管理员。" type="warning" :closable="false"/><div v-if="owned" aria-label="学习计时"><p class="muted">续播位置自动保存。累计折算时长达到视频时长的 90% 才完成，支持 0.5 至 2 倍速；暂停、缓冲、隐藏页面和拖动不增加时长。</p><p v-if="timedRecord?.completionSource==='LEGACY'">已完成 · 沿用历史学习规则</p><p v-else>累计折算 {{timeLabel(timedRecord?.creditedMillis)}} / 完成门槛 {{timeLabel(timing.current.value?.requiredMillis??Math.ceil(Number(section.mediaDuration||0)*900))}}<span v-if="timedRecord?.finished"> · 已完成</span></p><p class="muted">计时记录播放会话，不作为实际观看或学时认证证明。</p><div v-if="timing.error.value" role="alert"><p>{{timing.error.value}}</p><el-button v-if="!timing.replaced.value" :disabled="timing.busy.value" @click="retryTiming">重试保存计时</el-button><el-button :disabled="timing.busy.value" @click="restartTiming">在当前页面重新开始计时</el-button></div></div></template><div class="note-composer"><div class="section-heading"><h3>随堂笔记</h3><RouterLink to="/notes">全部笔记 →</RouterLink></div><el-input v-model="note" type="textarea" :rows="4" maxlength="10000" placeholder="记录私人笔记"/><div class="toolbar"><small>仅自己可见 · {{moment}} 秒</small><el-button type="primary" @click="saveNote" :disabled="!note.trim() || busy || !owned">保存笔记</el-button></div></div></template><div v-else class="workspace-empty"><div class="workspace-play">▶</div><h3>{{owned?'准备好开始学习了吗？':'先了解这门课程'}}</h3><p class="muted">{{owned?'选择左侧小节，继续你的学习。':'查看目录，报名后即可开始学习和记录笔记。'}}</p><el-button v-if="owned" type="primary" @click="continueLearning">开始学习</el-button></div></article></div>
<article v-show="tab==='discussion' || section" class="card discussion"><div class="section-heading"><div><h2>课程互动</h2><p class="muted">遇到问题？和同学一起交流思路。</p></div><el-switch v-model="onlyMine" active-text="我的提问" @change="questionPage=1;loadQuestions()"/><el-button @click="loadQuestions" :disabled="busy">查看讨论</el-button></div><el-empty v-if="discussionLoaded && !questions.length" description="还没有讨论，来提出第一个问题吧"/><div v-for="item in questions" :key="item.id" class="section"><el-button link @click="answers(item)">{{item.title}}</el-button><p>{{item.description}}</p><small>{{item.acceptedReplyId?'已有采纳回答':item.answerTimes?'已有回复':'等待回复'}}</small></div><el-pagination v-if="questionTotal>20" v-model:current-page="questionPage" :total="questionTotal" :page-size="20" layout="prev,pager,next" @current-change="loadQuestions"/><div class="question-composer"><p v-if="!section" class="muted">先在课程目录选择一个小节，再发起提问。</p><el-input v-model="title" placeholder="问题标题" maxlength="200"/><el-input v-model="description" type="textarea" placeholder="描述问题" :rows="3"/><el-button type="primary" @click="ask" :disabled="!title.trim() || !description.trim() || !section || busy || !owned">在当前小节提问</el-button></div>
<div v-if="question"><h3>{{question.title}}</h3><el-button v-if="!repliesReady" @click="answers(question)" :disabled="repliesLoading">重新加载回答</el-button><article v-for="item in replies" :key="item.id" class="section"><p class="content">{{item.content}}</p><el-button :type="item.liked?'primary':'default'" :aria-pressed="!!item.liked" :disabled="busy" @click="like(item)">{{item.liked?'已赞':'赞'}} {{item.likedTimes||0}}</el-button></article><el-pagination v-if="replyTotal>20" v-model:current-page="replyPage" :total="replyTotal" :page-size="20" layout="prev,pager,next" @current-change="question&&answers(question)"/><el-input v-model="reply" type="textarea" placeholder="写下回答"/><el-button @click="respond" :disabled="!reply.trim() || busy || !owned || !repliesReady">提交回答</el-button></div></article></template></div></template>
